examples.setupTemplate:
var preferences by remember {
    mutableStateOf(
        MonarchAppearancePreferences(
            accent = MonarchTokens.Accents.rook,
            scheme = MonarchScheme.{{preferences.theme|pascal}},
            contrast = MonarchContrast.{{preferences.contrast|pascal}},
            motion = MonarchAppearanceMotion.{{preferences.motion|pascal}},
            density = MonarchAppearanceDensity.{{preferences.density|pascal}},
        ),
    )
}

